screenPanels.initJs:
function(container, apiUrl, tables) {
  const errorLogs = tables[0]?.records || [];
  const errorClassifications = tables[1]?.records || [];
  const supervisors = tables[2]?.records || [];
  const validationResults = tables[3]?.records || [];

  let selectedErrorId = null;
  let filteredErrors = [...errorLogs];

  // ===== KPI 計算 =====
  function updateKPIs() {
    const now = new Date();
    const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).toISOString();

    const pending = errorLogs.filter(e => e.ステータス === '未対応').length;
    const critical = errorLogs.filter(e => e.重要度 === 'CRITICAL').length;
    const today = errorLogs.filter(e => e.作成日時 >= todayStart).length;
    const resolved = errorLogs.filter(e => e.ステータス === '解決済み').length;
    const rate = errorLogs.length > 0 ? Math.round((resolved / errorLogs.length) * 100) : 0;

    container.querySelector('[data-testid="kpi-pending"]').textContent = pending;
    container.querySelector('[data-testid="kpi-critical"]').textContent = critical;
    container.querySelector('[data-testid="kpi-today"]').textContent = today;
    container.querySelector('[data-testid="kpi-rate"]').textContent = rate + '%';
  }

  // ===== テーブル再描画 =====
  function renderRows(rows) {
    const tbody = container.querySelector('#error-tbody');
    tbody.innerHTML = rows.map(r => {
      const severityColor = r.重要度 === 'CRITICAL' ? '#ff4444' : r.重要度 === 'ERROR' ? '#ff9900' : r.重要度 === 'WARNING' ? '#ffcc00' : '#4488ff';
      const statusColor = r.ステータス === '未対応' ? '#ff6666' : r.ステータス === '対応中' ? '#ffaa00' : r.ステータス === '解決済み' ? '#66cc66' : '#999999';
      return `
        <tr data-id="${r.エラーログID || r.id}" style="border-bottom:1px solid rgba(255,255,255,0.08); cursor:pointer; transition:background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background=''">
          <td style="padding:8px; color:var(--text);">${r.エラーコード || ''}</td>
          <td style="padding:8px; color:var(--text); font-family:monospace; font-size:11px;">${(r.受注データID || '').substring(0, 8)}</td>
          <td style="padding:8px;"><span style="background:${severityColor}; color:#fff; padding:2px 6px; border-radius:2px; font-size:11px; font-weight:600;">${r.重要度 || ''}</span></td>
          <td style="padding:8px; color:var(--text); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:120px;" title="${r.エラーメッセージ || ''}">${(r.エラーメッセージ || '').substring(0, 30)}</td>
          <td style="padding:8px;"><span style="background:${statusColor}; color:#fff; padding:2px 6px; border-radius:2px; font-size:11px; font-weight:600;">${r.ステータス || ''}</span></td>
          <td style="padding:8px; color:var(--text-muted); font-size:11px;">${r.作成日時 ? new Date(r.作成日時).toLocaleString('ja-JP', {month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit'}) : ''}</td>
        </tr>
      `;
    }).join('');
  }

  // ===== 詳細パネル表示 =====
  function showDetail(errorId) {
    const error = errorLogs.find(e => (e.エラーログID || e.id) === errorId);
    if (!error) return;

    selectedErrorId = errorId;
    const panel = container.querySelector('#detail-panel');
    const classification = errorClassifications.find(c => c.エラーコード === error.エラーコード) || {};
    const supervisor = supervisors.find(s => s.責任者ID === error.対応者ID) || {};

    panel.innerHTML = `
      <div style="border-bottom:1px solid rgba(255,255,255,0.12); padding-bottom:10px;">
        <div style="font-size:13px; font-weight:600; color:var(--text); margin-bottom:4px;">エラー詳細</div>
        <div style="font-size:11px; color:var(--text-muted);">ID: ${(errorId || '').substring(0, 8)}</div>
      </div>

      <div>
        <label style="font-size:11px; color:var(--text-muted); display:block; margin-bottom:3px;">エラーコード</label>
        <div style="font-size:12px; color:var(--text); padding:6px; background:rgba(0,0,0,0.25); border-radius:3px; font-family:monospace;">${error.エラーコード || ''}</div>
      </div>

      <div>
        <label style="font-size:11px; color:var(--text-muted); display:block; margin-bottom:3px;">メッセージ</label>
        <div style="font-size:11px; color:var(--text); padding:6px; background:rgba(0,0,0,0.25); border-radius:3px; word-break:break-word; max-height:80px; overflow-y:auto;">${error.エラーメッセージ || ''}</div>
      </div>

      <div>
        <label style="font-size:11px; color:var(--text-muted); display:block; margin-bottom:3px;">重要度</label>
        <select id="detail-severity" data-testid="detail-severity" style="width:100%; padding:6px 8px; border:1px solid rgba(255,255,255,0.18); border-radius:3px; background:rgba(0,0,0,0.25); color:var(--text); font-size:12px;">
          <option value="INFO" ${error.重要度 === 'INFO' ? 'selected' : ''}>INFO</option>
          <option value="WARNING" ${error.重要度 === 'WARNING' ? 'selected' : ''}>WARNING</option>
          <option value="ERROR" ${error.重要度 === 'ERROR' ? 'selected' : ''}>ERROR</option>
          <option value="CRITICAL" ${error.重要度 === 'CRITICAL' ? 'selected' : ''}>CRITICAL</option>
        </select>
      </div>

      <div>
        <label style="font-size:11px; color:var(--text-muted); display:block; margin-bottom:3px;">ステータス</label>
        <select id="detail-status" data-testid="detail-status" style="width:100%; padding:6px 8px; border:1px solid rgba(255,255,255,0.18); border-radius:3px; background:rgba(0,0,0,0.25); color:var(--text); font-size:12px;">
          <option value="未対応" ${error.ステータス === '未対応' ? 'selected' : ''}>未対応</option>
          <option value="対応中" ${error.ステータス === '対応中' ? 'selected' : ''}>対応中</option>
          <option value="解決済み" ${error.ステータス === '解決済み' ? 'selected' : ''}>解決済み</option>
          <option value="無視" ${error.ステータス === '無視' ? 'selected' : ''}>無視</option>
        </select>
      </div>

      <div>
        <label style="font-size:11px; color:var(--text-muted); display:block; margin-bottom:3px;">対応者</label>
        <select id="detail-supervisor" data-testid="detail-supervisor" style="width:100%; padding:6px 8px; border:1px solid rgba(255,255,255,0.18); border-radius:3px; background:rgba(0,0,0,0.25); color:var(--text); font-size:12px;">
          <option value="">未割当</option>
          ${supervisors.map(s => `<option value="${s.責任者ID}" ${error.対応者ID === s.責任者ID ? 'selected' : ''}>${s.責任者名}</option>`).join('')}
        </select>
      </div>

      <div>
        <label style="font-size:11px; color:var(--text-muted); display:block; margin-bottom:3px;">対応コメント</label>
        <textarea id="detail-comment" data-testid="detail-comment" style="width:100%; padding:6px 8px; border:1px solid rgba(255,255,255,0.18); border-radius:3px; background:rgba(0,0,0,0.25); color:var(--text); font-size:11px; resize:vertical; height:60px;">${error.対応コメント || ''}</textarea>
      </div>

      <div style="display:grid; grid-template-columns:1fr 1fr; gap:6px;">
        <button id="btn-update" data-testid="update-button" class="action-btn" style="padding:6px; font-size:11px;">更新</button>
        <button id="btn-notify" data-testid="notify-button" class="action-btn secondary" style="padding:6px; font-size:11px;">通知送信</button>
      </div>

      <div style="border-top:1px solid rgba(255,255,255,0.12); padding-top:10px; margin-top:10px;">
        <div style="font-size:11px; color:var(--text-muted); margin-bottom:6px;">分類情報</div>
        <div style="font-size:11px; color:var(--text); padding:6px; background:rgba(0,0,0,0.25); border-radius:3px; word-break:break-word;">${classification.エラー説明 || '（分類情報なし）'}</div>
      </div>

      <div style="border-top:1px solid rgba(255,255,255,0.12); padding-top:10px; margin-top:10px;">
        <div style="font-size:11px; color:var(--text-muted); margin-bottom:6px;">ログ詳細</div>
        <div style="font-size:10px; color:var(--text-muted); padding:6px; background:rgba(0,0,0,0.25); border-radius:3px; font-family:monospace; word-break:break-all; max-height:100px; overflow-y:auto;">${error.エラー詳細 || '（詳細なし）'}</div>
      </div>
    `;

    // 更新ボタン
    panel.querySelector('#btn-update').addEventListener('click', async () => {
      const updated = {
        ...error,
        重要度: panel.querySelector('#detail-severity').value,
        ステータス: panel.querySelector('#detail-status').value,
        対応者ID: panel.querySelector('#detail-supervisor').value,
        対応コメント: panel.querySelector('#detail-comment').value,
        更新日時: new Date().toISOString()
      };
      const result = await window.aivicApi.update(0, errorId, updated);
      if (result) {
        Object.assign(error, updated);
        renderRows(filteredErrors);
        updateKPIs();
        alert('エラー情報を更新しました');
      }
    });

    // 通知送信ボタン
    panel.querySelector('#btn-notify').addEventListener('click', async () => {
      const supervisorId = panel.querySelector('#detail-supervisor').value;
      if (!supervisorId) {
        alert('対応者を選択してください');
        return;
      }
      const notification = {
        バリデーション結果ID: error.バリデーション結果ID,
        受注データID: error.受注データID,
        エラー分類ID: error.エラーログID,
        責任者ID: supervisorId,
        通知タイプ: 'エラー通知',
        通知ステータス: '送信済',
        通知内容: `エラーコード: ${error.エラーコード}\n${error.エラーメッセージ}`,
        送信日時: new Date().toISOString()
      };
      const result = await window.aivicApi.save(4, notification);
      if (result) {
        alert('通知を送信しました');
      }
    });
  }

  // ===== 初期描画 =====
  updateKPIs();
  renderRows(filteredErrors);

  // ===== 行クリックで詳細表示 =====
  container.querySelector('#error-tbody').addEventListener('click', (e) => {
    const row = e.target.closest('tr');
    if (row) {
      showDetail(row.dataset.id);
    }
  });

  // ===== フィルタボタン =====
  container.querySelector('#btn-filter').addEventListener('click', () => {
    const code = container.querySelector('#filter-code').value.toLowerCase();
    const severity = container.querySelector('#filter-severity').value;
    const status = container.querySelector('#filter-status').value;

    filteredErrors = errorLogs.filter(e => {
      return (!code || (e.エラーコード || '').toLowerCase().includes(code)) &&
             (!severity || e.重要度 === severity) &&
             (!status || e.ステータス === status);
    });

    renderRows(filteredErrors);
  });

  // ===== CSVエクスポート =====
  container.querySelector('#btn-export').addEventListener('click', () => {
    const headers = ['エラーコード', '受注ID', '重要度', 'ステータス', 'エラーメッセージ', '発生日時', '対応者'];
    const rows = filteredErrors.map(e => [
      e.エラーコード || '',
      (e.受注データID || '').substring(0, 8),
      e.重要度 || '',
      e.ステータス || '',
      e.エラーメッセージ || '',
      e.作成日時 ? new Date(e.作成日時).toLocaleString('ja-JP') : '',
      supervisors.find(s => s.責任者ID === e.対応者ID)?.責任者名 || ''
    ]);
    const csv = '\uFEFF' + [headers, ...rows].map(r => r.map(c => `"${String(c).replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `error-log-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });
}

function(container, apiUrl, tables) {
  const errorLogTbody = container.querySelector("#error-log-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const detailContent = container.querySelector("#detail-content");
  const detailStatus = container.querySelector("#detail-status");
  const detailComment = container.querySelector("#detail-comment");
  const btnUpdateDetail = container.querySelector("#btn-update-detail");
  const btnReprocess = container.querySelector("#btn-reprocess");

  let allErrorLogs = [];
  let selectedLogId = null;

  // 1. 再描画関数
  function renderErrorLogs(logs) {
    errorLogTbody.innerHTML = logs.map(log => {
      const severityColor = log.重要度 === 'CRITICAL' ? '#ff6a00' : 
                           log.重要度 === 'ERROR' ? '#ff8c42' : 
                           log.重要度 === 'WARNING' ? '#ffc107' : '#4a90e2';
      const statusColor = log.ステータス === '解決済み' ? '#4caf50' : 
                         log.ステータス === '対応中' ? '#ff9800' : 
                         log.ステータス === '未対応' ? '#f44336' : '#9e9e9e';

      return `
        <tr data-id="${log.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.15s;">
          <td style="padding: 8px 12px; color: var(--text); font-family: monospace; font-size: 11px;">${(log.id || '').substring(0, 8)}</td>
          <td style="padding: 8px 12px; color: var(--text); font-family: monospace; font-size: 11px;">${(log.受注ID || '').substring(0, 8)}</td>
          <td style="padding: 8px 12px; color: var(--text-muted); font-size: 11px;">${log.発生日時 || '-'}</td>
          <td style="padding: 8px 12px; color: var(--primary); font-weight: 500; font-size: 11px;">${log.エラーコード || '-'}</td>
          <td style="padding: 8px 12px; font-size: 11px;">
            <span style="display: inline-block; padding: 2px 6px; background: ${severityColor}20; color: ${severityColor}; border-radius: 2px; font-weight: 500;">${log.重要度 || '-'}</span>
          </td>
          <td style="padding: 8px 12px; font-size: 11px;">
            <span style="display: inline-block; padding: 2px 6px; background: ${statusColor}20; color: ${statusColor}; border-radius: 2px; font-weight: 500;">${log.ステータス || '-'}</span>
          </td>
          <td style="padding: 8px 12px; color: var(--text-muted); font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 200px;">${log.エラーメッセージ || '-'}</td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    allErrorLogs = rows || [];
    renderErrorLogs(allErrorLogs);
  });

  // 3. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const errorCode = container.querySelector("#filter-error-code").value.toUpperCase();
    const orderId = container.querySelector("#filter-order-id").value;
    const channel = container.querySelector("#filter-channel").value;
    const status = container.querySelector("#filter-status").value;
    const severity = container.querySelector("#filter-severity").value;

    const filtered = allErrorLogs.filter(log => {
      if (dateFrom && log.発生日時 < dateFrom) return false;
      if (dateTo && log.発生日時 > dateTo) return false;
      if (errorCode && !log.エラーコード?.includes(errorCode)) return false;
      if (orderId && !log.受注ID?.includes(orderId)) return false;
      if (channel && log.チャネル !== channel) return false;
      if (status && log.ステータス !== status) return false;
      if (severity && log.重要度 !== severity) return false;
      return true;
    });

    renderErrorLogs(filtered);
  });

  // 4. リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-date-from").value = "";
    container.querySelector("#filter-date-to").value = "";
    container.querySelector("#filter-error-code").value = "";
    container.querySelector("#filter-order-id").value = "";
    container.querySelector("#filter-channel").value = "";
    container.querySelector("#filter-status").value = "";
    container.querySelector("#filter-severity").value = "";
    renderErrorLogs(allErrorLogs);
    detailPanel.style.display = "none";
  });

  // 5. 行クリックで詳細パネル表示
  errorLogTbody.addEventListener("click", (e) => {
    const row = e.target.closest("tr");
    if (!row) return;

    selectedLogId = row.dataset.id;
    const log = allErrorLogs.find(l => l.id === selectedLogId);
    if (!log) return;

    // 詳細内容を表示
    detailContent.innerHTML = `
      <div style="margin-bottom: 8px;">
        <strong style="color: var(--text);">ログID:</strong> ${log.id || '-'}
      </div>
      <div style="margin-bottom: 8px;">
        <strong style="color: var(--text);">受注ID:</strong> ${log.受注ID || '-'}
      </div>
      <div style="margin-bottom: 8px;">
        <strong style="color: var(--text);">エラーコード:</strong> ${log.エラーコード || '-'}
      </div>
      <div style="margin-bottom: 8px;">
        <strong style="color: var(--text);">エラーメッセージ:</strong><br />
        <span style="word-break: break-word;">${log.エラーメッセージ || '-'}</span>
      </div>
      <div style="margin-bottom: 8px;">
        <strong style="color: var(--text);">エラー詳細:</strong><br />
        <span style="word-break: break-word; font-family: monospace; font-size: 10px;">${log.エラー詳細 || '-'}</span>
      </div>
      <div style="margin-bottom: 8px;">
        <strong style="color: var(--text);">発生モジュール:</strong> ${log.発生モジュール || '-'}
      </div>
      <div style="margin-bottom: 8px;">
        <strong style="color: var(--text);">チャネル:</strong> ${log.チャネル || '-'}
      </div>
    `;

    detailStatus.value = log.ステータス || "未対応";
    detailComment.value = log.対応コメント || "";

    detailPanel.style.display = "flex";

    // 行をハイライト
    document.querySelectorAll("#error-log-tbody tr").forEach(tr => {
      tr.style.background = tr.dataset.id === selectedLogId ? "rgba(255,165,0,0.1)" : "";
    });
  });

  // 6. 詳細パネルの更新ボタン
  btnUpdateDetail.addEventListener("click", async () => {
    if (!selectedLogId) return;

    const updated = await window.aivicApi.update(0, selectedLogId, {
      ステータス: detailStatus.value,
      対応コメント: detailComment.value
    });

    if (updated) {
      // ローカルデータを更新
      const log = allErrorLogs.find(l => l.id === selectedLogId);
      if (log) {
        log.ステータス = detailStatus.value;
        log.対応コメント = detailComment.value;
      }
      renderErrorLogs(allErrorLogs);
      alert("更新しました");
    }
  });

  // 7. 再処理ボタン
  btnReprocess.addEventListener("click", async () => {
    if (!selectedLogId) return;

    if (!confirm("このエラーを再処理しますか？")) return;

    const updated = await window.aivicApi.update(0, selectedLogId, {
      ステータス: "対応中",
      再処理日時: new Date().toISOString()
    });

    if (updated) {
      alert("再処理を開始しました");
      window.aivicApi.list(0).then(rows => {
        allErrorLogs = rows || [];
        renderErrorLogs(allErrorLogs);
        detailPanel.style.display = "none";
      });
    }
  });
}

function(container, apiUrl, tables) {
  const errorList = tables[0]?.records || [];
  const tbody = container.querySelector("#error-tbody");
  const detailModal = container.querySelector("#detail-modal");
  const detailContent = container.querySelector("#detail-content");
  const closeDetailBtn = container.querySelector("#close-detail");
  let currentErrorId = null;
  let filteredData = [...errorList];

  // ステータス色マッピング
  const statusColors = {
    "未対応": "#e74c3c",
    "対応中": "#d4a574",
    "解決済み": "#27ae60",
    "無視": "#95a5a6"
  };

  const priorityColors = {
    "CRITICAL": "#e74c3c",
    "ERROR": "#e67e22",
    "WARNING": "#f39c12",
    "INFO": "#3498db"
  };

  // 1. 再描画関数
  function renderRows(rows) {
    if (rows.length === 0) {
      tbody.innerHTML = `<tr style="background: rgba(0,0,0,0.1);"><td colspan="8" style="padding: 2rem; text-align: center; color: var(--text-muted);">該当するエラーがありません</td></tr>`;
      updateKPIs([]);
      return;
    }
    tbody.innerHTML = rows.map(r => {
      const statusColor = statusColors[r.ステータス] || "#95a5a6";
      const priorityColor = priorityColors[r.優先度] || "#3498db";
      const errorId = r.エラーログID || r.id || "";
      return `<tr data-id="${errorId}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;">
        <td style="padding: 0.5rem; color: var(--text);">${r.エラーコード || "-"}</td>
        <td style="padding: 0.5rem; color: var(--text);">${r.受注番号 || "-"}</td>
        <td style="padding: 0.5rem; color: var(--text);">${r.エラー分類名 || "-"}</td>
        <td style="padding: 0.5rem; color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${r.エラーメッセージ || "-"}</td>
        <td style="padding: 0.5rem; text-align: center;"><span style="background: ${priorityColor}; color: #fff; padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; font-weight: 600;">${r.優先度 || "INFO"}</span></td>
        <td style="padding: 0.5rem; text-align: center;"><span style="background: ${statusColor}; color: #fff; padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; font-weight: 600;">${r.ステータス || "未対応"}</span></td>
        <td style="padding: 0.5rem; color: var(--text); font-size: 0.8rem;">${r.発生日時 ? new Date(r.発生日時).toLocaleString('ja-JP') : "-"}</td>
        <td style="padding: 0.5rem; text-align: center;"><button class="action-btn secondary detail-btn" data-id="${errorId}" style="padding: 0.25rem 0.75rem; font-size: 0.75rem;">詳細</button></td>
      </tr>`;
    }).join("");
    updateKPIs(rows);
  }

  // KPI 更新
  function updateKPIs(rows) {
    const unresolved = rows.filter(r => r.ステータス === "未対応").length;
    const inprogress = rows.filter(r => r.ステータス === "対応中").length;
    const today = rows.filter(r => {
      const d = new Date(r.発生日時);
      const now = new Date();
      return d.toDateString() === now.toDateString();
    }).length;
    const resolved = rows.filter(r => r.ステータス === "解決済み").length;

    container.querySelector("[data-testid='kpi-unresolved']").textContent = unresolved;
    container.querySelector("[data-testid='kpi-inprogress']").textContent = inprogress;
    container.querySelector("[data-testid='kpi-today']").textContent = today;
    container.querySelector("[data-testid='kpi-resolved']").textContent = resolved;
  }

  // 2. 初期データ描画
  renderRows(filteredData);

  // 3. 詳細表示
  function showDetail(errorId) {
    const error = filteredData.find(r => (r.エラーログID || r.id) === errorId);
    if (!error) return;
    currentErrorId = errorId;
    detailContent.innerHTML = `
      <div>
        <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">エラーID</div>
        <div style="color: var(--text); font-weight: 500;">${error.エラーコード || "-"}</div>
      </div>
      <div>
        <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">受注番号</div>
        <div style="color: var(--text); font-weight: 500;">${error.受注番号 || "-"}</div>
      </div>
      <div>
        <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">エラー分類</div>
        <div style="color: var(--text); font-weight: 500;">${error.エラー分類名 || "-"}</div>
      </div>
      <div>
        <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">エラー内容</div>
        <div style="color: var(--text); font-weight: 500; word-break: break-word;">${error.エラーメッセージ || "-"}</div>
      </div>
      <div>
        <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">エラー詳細</div>
        <div style="color: var(--text); font-weight: 500; word-break: break-word; font-family: monospace; font-size: 0.8rem; background: rgba(0,0,0,0.2); padding: 0.5rem; border-radius: 0.25rem; max-height: 150px; overflow-y: auto;">${error.エラー詳細 || "-"}</div>
      </div>
      <div>
        <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">優先度</div>
        <div style="color: var(--text); font-weight: 500;">${error.優先度 || "INFO"}</div>
      </div>
      <div>
        <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">ステータス</div>
        <div style="color: var(--text); font-weight: 500;">${error.ステータス || "未対応"}</div>
      </div>
      <div>
        <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">発生日時</div>
        <div style="color: var(--text); font-weight: 500;">${error.発生日時 ? new Date(error.発生日時).toLocaleString('ja-JP') : "-"}</div>
      </div>
      <div>
        <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">責任者</div>
        <div style="color: var(--text); font-weight: 500;">${error.責任者名 || "-"}</div>
      </div>
    `;
    detailModal.style.display = "flex";
  }

  // 4. フィルタ処理
  function applyFilters() {
    const responsible = container.querySelector("[data-testid='filter-responsible']").value;
    const category = container.querySelector("[data-testid='filter-category']").value;
    const priority = container.querySelector("[data-testid='filter-priority']").value;
    const status = container.querySelector("[data-testid='filter-status']").value;
    const dateFrom = container.querySelector("[data-testid='filter-date-from']").value;

    filteredData = errorList.filter(r => {
      if (responsible && r.部門名 !== responsible) return false;
      if (category && r.エラー分類名 !== category) return false;
      if (priority && r.優先度 !== priority) return false;
      if (status && r.ステータス !== status) return false;
      if (dateFrom) {
        const rDate = new Date(r.発生日時).toDateString();
        const fDate = new Date(dateFrom).toDateString();
        if (rDate < fDate) return false;
      }
      return true;
    });
    renderRows(filteredData);
  }

  // 5. イベントリスナー
  container.querySelector("[data-testid='filter-button']").addEventListener("click", applyFilters);
  container.querySelector("[data-testid='filter-reset']").addEventListener("click", () => {
    container.querySelector("[data-testid='filter-responsible']").value = "";
    container.querySelector("[data-testid='filter-category']").value = "";
    container.querySelector("[data-testid='filter-priority']").value = "";
    container.querySelector("[data-testid='filter-status']").value = "";
    container.querySelector("[data-testid='filter-date-from']").value = "";
    filteredData = [...errorList];
    renderRows(filteredData);
  });

  container.querySelector("[data-testid='refresh-button']").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (rows) {
      errorList.length = 0;
      errorList.push(...rows);
      filteredData = [...errorList];
      renderRows(filteredData);
    }
  });

  closeDetailBtn.addEventListener("click", () => {
    detailModal.style.display = "none";
    currentErrorId = null;
  });

  detailModal.addEventListener("click", (e) => {
    if (e.target === detailModal) {
      detailModal.style.display = "none";
      currentErrorId = null;
    }
  });

  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
    }
  });

  container.querySelector("#btn-assign").addEventListener("click", async () => {
    if (!currentErrorId) return;
    const error = filteredData.find(r => (r.エラーログID || r.id) === currentErrorId);
    if (error) {
      error.ステータス = "対応中";
      await window.aivicApi.update(0, currentErrorId, { ステータス: "対応中" });
      renderRows(filteredData);
      detailModal.style.display = "none";
    }
  });

  container.querySelector("#btn-resolve").addEventListener("click", async () => {
    if (!currentErrorId) return;
    const error = filteredData.find(r => (r.エラーログID || r.id) === currentErrorId);
    if (error) {
      error.ステータス = "解決済み";
      await window.aivicApi.update(0, currentErrorId, { ステータス: "解決済み" });
      renderRows(filteredData);
      detailModal.style.display = "none";
    }
  });

  container.querySelector("#btn-ignore").addEventListener("click", async () => {
    if (!currentErrorId) return;
    const error = filteredData.find(r => (r.エラーログID || r.id) === currentErrorId);
    if (error) {
      error.ステータス = "無視";
      await window.aivicApi.update(0, currentErrorId, { ステータス: "無視" });
      renderRows(filteredData);
      detailModal.style.display = "none";
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const integrationHistoryIdx = tables.findIndex(t => t.tableName === '基幹システム連携履歴');
  const errorLogIdx = tables.findIndex(t => t.tableName === 'エラーログ');
  const errorCategoryIdx = tables.findIndex(t => t.tableName === 'エラー分類マスタ');
  const responsibleIdx = tables.findIndex(t => t.tableName === '責任者マスタ');

  const timelineContainer = container.querySelector('#timeline-container');
  const detailPanelEmpty = container.querySelector('#detail-panel-empty');
  const detailPanelContent = container.querySelector('#detail-panel-content');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const refreshBtn = container.querySelector('[data-testid="refresh-button"]');
  const exportBtn = container.querySelector('[data-testid="export-csv"]');
  const navValidationBtn = container.querySelector('[data-testid="nav-validation"]');

  let currentDetailId = null;
  let allIntegrationRecords = [];
  let allErrorRecords = [];

  // KPI 更新関数
  function updateKPI(records) {
    const total = records.length;
    const success = records.filter(r => r.処理ステータス === '成功').length;
    const failure = records.filter(r => r.処理ステータス === '失敗').length;
    const partial = records.filter(r => r.処理ステータス === '部分成功').length;
    const warning = partial;

    container.querySelector('[data-testid="kpi-total-count"]').textContent = total;
    container.querySelector('[data-testid="kpi-success-count"]').textContent = success;
    container.querySelector('[data-testid="kpi-error-count"]').textContent = failure;
    container.querySelector('[data-testid="kpi-warning-count"]').textContent = warning;
  }

  // タイムラインアイテムの描画
  function renderTimeline(records) {
    timelineContainer.innerHTML = records.map(record => {
      const statusColor = record.処理ステータス === '成功' ? '#4ade80' : 
                         record.処理ステータス === '失敗' ? '#ef4444' : '#f97316';
      const statusLabel = record.処理ステータス === '成功' ? '✓' : 
                         record.処理ステータス === '失敗' ? '✕' : '⚠';

      return `
        <div class="card" data-id="${record.連携履歴ID}" style="padding: 0.5rem; cursor: pointer; border-left: 3px solid ${statusColor}; transition: background 0.2s;" 
             onmouseover="this.style.background='rgba(255,255,255,0.05)'" 
             onmouseout="this.style.background='transparent'">
          <div style="display: flex; justify-content: space-between; align-items: start; gap: 0.5rem;">
            <div style="flex: 1;">
              <div style="display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.25rem;">
                <span style="font-size: 1.25rem; color: ${statusColor}; font-weight: 700;">${statusLabel}</span>
                <span style="font-size: 0.875rem; font-weight: 600; color: var(--text);">${record.連携種別 || '連携'}</span>
                <span style="font-size: 0.75rem; color: var(--text-muted);">${record.連携方向 || ''}</span>
              </div>
              <div style="font-size: 0.75rem; color: var(--text-muted); margin-bottom: 0.25rem;">
                ${new Date(record.実行開始日時).toLocaleString('ja-JP')}
              </div>
              <div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 0.5rem; font-size: 0.75rem;">
                <div><span style="color: var(--text-muted);">送信:</span> <span style="color: var(--text); font-weight: 600;">${record.送信データ件数 || 0}</span></div>
                <div><span style="color: var(--text-muted);">成功:</span> <span style="color: #4ade80; font-weight: 600;">${record.成功件数 || 0}</span></div>
                <div><span style="color: var(--text-muted);">失敗:</span> <span style="color: #ef4444; font-weight: 600;">${record.失敗件数 || 0}</span></div>
                <div><span style="color: var(--text-muted);">時間:</span> <span style="color: var(--text); font-weight: 600;">${record.処理時間秒 || 0}s</span></div>
              </div>
            </div>
          </div>
        </div>
      `;
    }).join('');

    // タイムラインアイテムのクリックイベント
    container.querySelectorAll('#timeline-container .card').forEach(item => {
      item.addEventListener('click', () => {
        const id = item.dataset.id;
        showDetail(id);
      });
    });
  }

  // 詳細パネルの表示
  function showDetail(integrationId) {
    currentDetailId = integrationId;
    const record = allIntegrationRecords.find(r => r.連携履歴ID === integrationId);

    if (!record) return;

    detailPanelEmpty.style.display = 'none';
    detailPanelContent.style.display = 'flex';

    container.querySelector('#detail-integration-id').textContent = record.連携履歴ID;
    container.querySelector('#detail-integration-type').textContent = record.連携種別 || '-';
    container.querySelector('#detail-status').textContent = record.処理ステータス || '-';
    container.querySelector('#detail-exec-time').textContent = new Date(record.実行開始日時).toLocaleString('ja-JP');
    container.querySelector('#detail-duration').textContent = (record.処理時間秒 || 0) + ' 秒';
    container.querySelector('#detail-sent-count').textContent = record.送信データ件数 || 0;
    container.querySelector('#detail-success-count').textContent = record.成功件数 || 0;
    container.querySelector('#detail-failure-count').textContent = record.失敗件数 || 0;
    container.querySelector('#detail-skip-count').textContent = (record.送信データ件数 - record.成功件数 - record.失敗件数) || 0;
    container.querySelector('#detail-error-message').textContent = record.エラー詳細 || record.エラー詳細 || '（エラーなし）';
    container.querySelector('#detail-responsible').textContent = record.実行ユーザーID || '-';
  }

  // 検索・フィルター処理
  function applyFilters() {
    const dateFrom = container.querySelector('[data-testid="filter-date-from"]').value;
    const dateTo = container.querySelector('[data-testid="filter-date-to"]').value;
    const orderId = container.querySelector('[data-testid="search-order-id"]').value.toLowerCase();
    const errorCategory = container.querySelector('[data-testid="filter-error-category"]').value;
    const responsible = container.querySelector('[data-testid="filter-responsible"]').value;

    let filtered = allIntegrationRecords.filter(r => {
      const execDate = new Date(r.実行開始日時).toISOString().split('T')[0];
      if (dateFrom && execDate < dateFrom) return false;
      if (dateTo && execDate > dateTo) return false;
      if (orderId && !JSON.stringify(r).toLowerCase().includes(orderId)) return false;
      if (responsible && r.実行ユーザーID !== responsible) return false;
      return true;
    });

    if (errorCategory) {
      filtered = filtered.filter(r => {
        if (errorCategory === 'validation') return r.処理ステータス === '실패' && r.エラー詳細?.includes('validation');
        if (errorCategory === 'system') return r.処理ステータス === '실패' && r.エ러_詳細?.includes('system');
        if (errorCategory === 'integration') return r.처리ステータス === '실패';
        if (errorCategory === 'warning') return r.처리ステータス === '부분성공';
        return true;
      });
    }

    // 최신순으로 정렬
    filtered.sort((a, b) => new Date(b.実行開始日時) - new Date(a.実行開始日時));

    updateKPI(filtered);
    renderTimeline(filtered);
    detailPanelEmpty.style.display = 'block';
    detailPanelContent.style.display = 'none';
  }

  // CSV エクスポート
  function exportToCSV() {
    if (allIntegrationRecords.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['連携履歴ID', '連携種別', '連携方向', '処理ステータス', '送信データ件数', '成功件数', '失敗件数', '実行開始日時', '処理時間秒', 'エラー詳細'];
    const rows = allIntegrationRecords.map(r => [
      r.連携履歴ID,
      r.連携種別,
      r.連携方向,
      r.処理ステータス,
      r.送信データ件数,
      r.成功件数,
      r.失敗件数,
      new Date(r.実行開始日時).toLocaleString('ja-JP'),
      r.処理時間秒,
      r.エラー詳細
    ]);

    const csv = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => {
        const str = String(cell || '');
        return str.includes(',') || str.includes('"') || str.includes('\n') 
          ? `"${str.replace(/"/g, '""')}"` 
          : str;
      }).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `連携結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー登録
  searchBtn.addEventListener('click', applyFilters);
  refreshBtn.addEventListener('click', () => {
    window.aivicApi.list(integrationHistoryIdx).then(records => {
      allIntegrationRecords = records || [];
      applyFilters();
    });
  });
  exportBtn.addEventListener('click', exportToCSV);

  container.querySelector('[data-testid="detail-view-log"]').addEventListener('click', () => {
    if (currentDetailId) {
      window.showScreen('scr-1781408467707');
    }
  });

  container.querySelector('[data-testid="detail-retry"]').addEventListener('click', () => {
    if (currentDetailId && confirm('この連携を再実行しますか？')) {
      alert('再実行処理を開始しました');
    }
  });

  navValidationBtn.addEventListener('click', () => {
    window.showScreen('scr-1781408454309');
  });

  // 初期データ読み込み
  window.aivicApi.list(integrationHistoryIdx).then(records => {
    allIntegrationRecords = records || [];
    applyFilters();
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const orderTableIndex = 0;
  const validationTableIndex = 1;
  const errorLogTableIndex = 2;

  // 状態管理
  let allOrders = [];
  let validationResults = [];
  let errorLogs = [];
  let currentTab = 'all';
  let selectedOrderIds = new Set();

  // ========== 1. 受注データ一覧の再描画 ==========
  function renderOrderList(orders) {
    const tbody = container.querySelector('#order-tbody');
    if (!orders || orders.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);"><td colspan="4" style="padding: 12px 8px; text-align: center; color: var(--text-muted); font-size: 11px;">該当する受注データがありません</td></tr>';
      return;
    }
    tbody.innerHTML = orders.map(order => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;" data-id="${order.id}" class="order-row">
        <td style="padding: 6px 8px; color: var(--text);">${order.受注番号 || ''}</td>
        <td style="padding: 6px 8px; color: var(--text); font-size: 11px;">${order.受注日 ? new Date(order.受注日).toLocaleDateString('ja-JP') : ''}</td>
        <td style="padding: 6px 8px; text-align: right; color: var(--text);">¥${(order.受注金額 || 0).toLocaleString()}</td>
        <td style="padding: 6px 8px; color: var(--text);"><span style="background: rgba(76,175,80,0.2); color: #4caf50; padding: 2px 6px; border-radius: 3px; font-size: 10px;">${order.ステータス || '未処理'}</span></td>
      </tr>
    `).join('');
  }

  // ========== 2. エラー詳細テーブルの再描画 ==========
  function renderErrorDetails(errors) {
    const tbody = container.querySelector('#error-detail-tbody');
    if (!errors || errors.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);"><td colspan="4" style="padding: 12px 8px; text-align: center; color: var(--text-muted); font-size: 11px;">エラーはありません</td></tr>';
      return;
    }
    tbody.innerHTML = errors.map(err => {
      const severityColor = err.重要度 === 'CRITICAL' ? '#ff6b6b' : err.重要度 === 'WARNING' ? '#ffc107' : '#4caf50';
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 8px; color: var(--text); font-size: 11px;">${err.受注番号 || ''}</td>
          <td style="padding: 6px 8px; color: var(--text); font-size: 11px;">${err.エラー分類 || ''}</td>
          <td style="padding: 6px 8px; color: var(--text); font-size: 11px;">${err.エラーメッセージ || ''}</td>
          <td style="padding: 6px 8px;"><span style="background: rgba(${severityColor === '#ff6b6b' ? '255,107,107' : severityColor === '#ffc107' ? '255,193,7' : '76,175,80'},0.2); color: ${severityColor}; padding: 2px 6px; border-radius: 3px; font-size: 10px;">${err.重要度 || 'INFO'}</span></td>
        </tr>
      `;
    }).join('');
  }

  // ========== 3. 初期データ読み込み ==========
  async function initData() {
    try {
      allOrders = await window.aivicApi.list(orderTableIndex) || tables[orderTableIndex]?.records || [];
      renderOrderList(allOrders);
    } catch (e) {
      console.error('Failed to load orders:', e);
      allOrders = tables[orderTableIndex]?.records || [];
      renderOrderList(allOrders);
    }
  }

  // ========== 4. 検索ボタン ==========
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const orderNo = container.querySelector('#filter-order-no').value.trim();
    const status = container.querySelector('#filter-status').value;
    const dateFrom = container.querySelector('#filter-date-from').value;
    const dateTo = container.querySelector('#filter-date-to').value;

    let filtered = allOrders;
    if (orderNo) filtered = filtered.filter(o => (o.受注番号 || '').includes(orderNo));
    if (status) filtered = filtered.filter(o => o.ステータス === status);
    if (dateFrom) filtered = filtered.filter(o => new Date(o.受注日) >= new Date(dateFrom));
    if (dateTo) filtered = filtered.filter(o => new Date(o.受注日) <= new Date(dateTo));

    renderOrderList(filtered);
  });

  // ========== 5. バリデーション実行ボタン ==========
  container.querySelector('#btn-validate').addEventListener('click', async () => {
    // 選択された受注IDを収集
    selectedOrderIds.clear();
    container.querySelectorAll('#order-tbody tr[data-id]').forEach(row => {
      selectedOrderIds.add(row.dataset.id);
    });

    if (selectedOrderIds.size === 0) {
      alert('バリデーション対象の受注データがありません');
      return;
    }

    // ダミーバリデーション結果を生成
    validationResults = [];
    errorLogs = [];
    let errorCount = 0, warningCount = 0, successCount = 0;

    allOrders.forEach((order, idx) => {
      if (selectedOrderIds.has(order.id)) {
        // ランダムにエラーを生成（デモ用）
        const rand = Math.random();
        if (rand < 0.3) {
          // エラー
          validationResults.push({
            id: `val-${order.id}`,
            受注番号: order.受注番号,
            エラー分類: ['データ型エラー', '必須項目エラー', '範囲エラー'][Math.floor(Math.random() * 3)],
            エラーメッセージ: '受注金額が無効な形式です',
            重要度: 'CRITICAL',
            ステータス: '失敗'
          });
          errorCount++;
          errorLogs.push(`[ERROR] 受注${order.受注番号}: 受注金額バリデーション失敗 - 値が範囲外です`);
        } else if (rand < 0.6) {
          // 警告
          validationResults.push({
            id: `val-${order.id}`,
            受注番号: order.受注番号,
            エラー分類: '範囲エラー',
            エラーメッセージ: '受注金額が高額です',
            重要度: 'WARNING',
            ステータス: '警告'
          });
          warningCount++;
          errorLogs.push(`[WARNING] 受注${order.受注番号}: 受注金額が与信限度額に近い`);
        } else {
          // 成功
          successCount++;
          errorLogs.push(`[INFO] 受注${order.受注番号}: バリデーション成功`);
        }
      }
    });

    // サマリー更新
    container.querySelector('#error-count').textContent = errorCount;
    container.querySelector('#warning-count').textContent = warningCount;
    container.querySelector('#success-count').textContent = successCount;

    // エラーログ表示
    container.querySelector('#error-log').textContent = errorLogs.slice(-10).join('\n');

    // タブ「すべて」を選択
    currentTab = 'all';
    updateTabs();
    renderErrorDetails(validationResults);
  });

  // ========== 6. エラー分類タブ切り替え ==========
  function updateTabs() {
    container.querySelectorAll('.tab-btn').forEach(btn => {
      if (btn.dataset.tab === currentTab) {
        btn.style.color = 'var(--text)';
        btn.style.borderBottomColor = 'var(--primary)';
        btn.style.fontWeight = '600';
      } else {
        btn.style.color = 'var(--text-muted)';
        btn.style.borderBottomColor = 'transparent';
        btn.style.fontWeight = '400';
      }
    });

    let filtered = validationResults;
    if (currentTab === 'validation') filtered = validationResults.filter(e => e.エラー分類 === 'データ型エラー');
    else if (currentTab === 'required') filtered = validationResults.filter(e => e.エラー分類 === '必須項目エラー');
    else if (currentTab === 'range') filtered = validationResults.filter(e => e.エラー分類 === '範囲エラー');
    else if (currentTab === 'system') filtered = validationResults.filter(e => e.エラー分類 === 'システムエラー');

    renderErrorDetails(filtered);
  }

  container.querySelectorAll('.tab-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      currentTab = btn.dataset.tab;
      updateTabs();
    });
  });

  // ========== 7. 通知送信ボタン ==========
  container.querySelector('#btn-notify').addEventListener('click', async () => {
    const responsibleUser = container.querySelector('#responsible-user').value;
    const notifyEmail = container.querySelector('#notify-email').checked;
    const notifySlack = container.querySelector('#notify-slack').checked;
    const message = container.querySelector('#notify-message').value;

    if (!responsibleUser) {
      alert('責任者を選択してください');
      return;
    }

    if (!notifyEmail && !notifySlack) {
      alert('通知チャネルを選択してください');
      return;
    }

    // 通知送信処理（ダミー）
    const channels = [];
    if (notifyEmail) channels.push('メール');
    if (notifySlack) channels.push('Slack');

    alert(`通知を送信しました\n責任者: ${responsibleUser}\nチャネル: ${channels.join(', ')}`);
    container.querySelector('#notify-message').value = '';
  });

  // ========== 8. 承認・送信ボタン ==========
  container.querySelector('#btn-approve').addEventListener('click', async () => {
    if (validationResults.length === 0) {
      alert('バリデーション結果がありません');
      return;
    }

    const errorCount = parseInt(container.querySelector('#error-count').textContent);
    if (errorCount > 0) {
      if (!confirm(`${errorCount}件のエラーがあります。それでも送信しますか？`)) {
        return;
      }
    }

    // 承認・送信処理（ダミー）
    alert('受注データを基幹システムに送信しました');
    container.querySelector('#error-log').textContent += '\n[INFO] 基幹システム連携: 送信完了';
  });

  // ========== 9. 初期化 ==========
  initData();
}

function(container, apiUrl, tables) {
  // テーブルインデックスの確認
  const validationResultIdx = tables.findIndex(t => t.tableName === 'バリデーション結果') ?? 0;
  const errorLogIdx = tables.findIndex(t => t.tableName === 'エラーログ') ?? 1;
  const errorClassificationIdx = tables.findIndex(t => t.tableName === 'エラー分類マスタ') ?? 2;

  // エラー分類テーブルの再描画
  function renderErrorClassification(rows) {
    const tbody = container.querySelector('#error-classification-tbody');
    if (!tbody) return;
    tbody.innerHTML = (rows || []).slice(0, 10).map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 8px 6px; color: var(--text);">${r.エラーコード || r.errorCode || ''}</td>
        <td style="padding: 8px 6px; color: var(--text);">${r.エラー分類名 || r.errorClassName || ''}</td>
        <td style="padding: 8px 6px; text-align: center; color: var(--text);">${r.件数 || r.count || 0}</td>
        <td style="padding: 8px 6px; text-align: center;">
          <span style="background: ${r.重要度レベル === 'CRITICAL' ? 'rgba(239,68,68,0.2)' : 'rgba(251,191,36,0.2)'}; color: ${r.重要度レベル === 'CRITICAL' ? '#fca5a5' : '#fde047'}; padding: 2px 6px; border-radius: 3px; font-size: 11px;">
            ${r.重要度レベル || r.severity || 'INFO'}
          </span>
        </td>
      </tr>
    `).join('');
  }

  // 初期データ表示
  if (tables[errorClassificationIdx]?.records) {
    renderErrorClassification(tables[errorClassificationIdx].records);
  }

  // バリデーション実行ボタン
  const executeBtn = container.querySelector('[data-testid="execute-validation"]');
  if (executeBtn) {
    executeBtn.addEventListener('click', async () => {
      const periodFrom = container.querySelector('[data-testid="period-from"]').value;
      const periodTo = container.querySelector('[data-testid="period-to"]').value;
      const channel = container.querySelector('[data-testid="channel-filter"]').value;
      const rule = container.querySelector('[data-testid="validation-rule"]').value;

      if (!periodFrom || !periodTo || !rule) {
        alert('期間とバリデーションルールを選択してください');
        return;
      }

      // バリデーション実行（シミュレーション）
      alert(`バリデーション実行\n期間: ${periodFrom} ～ ${periodTo}\nチャネル: ${channel || '全て'}\nルール: ${rule}`);

      // 実際の API 呼び出し（オプション）
      const result = await window.aivicApi.save(validationResultIdx, {
        periodFrom,
        periodTo,
        channel,
        rule,
        executedAt: new Date().toISOString(),
        executedBy: 'user-001'
      });

      if (result) {
        // 結果を再描画
        const updated = await window.aivicApi.list(errorClassificationIdx);
        renderErrorClassification(updated);
      }
    });
  }

  // 詳細ログ表示ボタン
  const viewDetailsBtn = container.querySelector('[data-testid="view-error-details"]');
  if (viewDetailsBtn) {
    viewDetailsBtn.addEventListener('click', () => {
      window.showScreen('scr-1781408467707');
    });
  }

  // 顧客マスタ参照ボタン
  const customerLookupBtn = container.querySelector('[data-testid="customer-lookup"]');
  if (customerLookupBtn) {
    customerLookupBtn.addEventListener('click', () => {
      const searchValue = container.querySelector('[data-testid="customer-search"]').value;
      if (!searchValue) {
        alert('顧客コードまたは名称を入力してください');
        return;
      }
      alert(`顧客マスタ参照: ${searchValue}`);
    });
  }

  // 責任者割当ボタン
  const assignBtn = container.querySelector('[data-testid="assign-responsible"]');
  if (assignBtn) {
    assignBtn.addEventListener('click', async () => {
      const errorCategory = container.querySelector('[data-testid="error-category-assign"]').value;
      const responsible = container.querySelector('[data-testid="responsible-person"]').value;

      if (!errorCategory || !responsible) {
        alert('エラー分類と責任者を選択してください');
        return;
      }

      alert(`責任者割当\nエラー分類: ${errorCategory}\n責任者: ${responsible}`);
    });
  }

  // 連携実行へ進むボタン
  const proceedBtn = container.querySelector('[data-testid="proceed-integration"]');
  if (proceedBtn) {
    proceedBtn.addEventListener('click', () => {
      window.showScreen('scr-1781408509581');
    });
  }

  // 初期データ読み込み（最新データを取得）
  (async () => {
    const validationResults = await window.aivicApi.list(validationResultIdx);
    if (validationResults && validationResults.length > 0) {
      // KPI 更新（オプション）
      const total = validationResults.length;
      const success = validationResults.filter(r => r.検証ステータス === '成功').length;
      const warning = validationResults.filter(r => r.検証ステータス === '警告').length;
      const error = validationResults.filter(r => r.検証ステータス === '失敗').length;

      container.querySelector('[data-testid="kpi-total"]').textContent = total.toLocaleString();
      container.querySelector('[data-testid="kpi-success"]').textContent = success.toLocaleString();
      container.querySelector('[data-testid="kpi-warning"]').textContent = warning.toLocaleString();
      container.querySelector('[data-testid="kpi-error"]').textContent = error.toLocaleString();
    }

    const errorClassifications = await window.aivicApi.list(errorClassificationIdx);
    if (errorClassifications) {
      renderErrorClassification(errorClassifications);
    }
  })();
}
